(5013499, 730339, 95579, '<td valign="top">Unusual! Nice lighting</td>', 'Unusual! Nice lighting', '2008-10-18 13:14:14.000000', NULL, 1),
(5013500, 731052, 86447, '<td valign="top">A good image... but not really exciting.  I gave it a 5...  <br/>I like the focus and the leaves being the same color as Woody.</td>', 'A good image... but not really exciting.  I gave it a 5...  I like the focus and the leaves being the same color as Woody.', '2008-10-18 13:14:21.000000', NULL, 1),
(5013501, 730755, 3087, '<td valign="top">Cute, clever, simple.</td>', 'Cute, clever, simple.', '2008-10-18 13:17:37.000000', NULL, 1),
(5013502, 729543, 86447, '<td valign="top">Nice and sharp and interesting.  I like the contrast and IR look.</td>', 'Nice and sharp and interesting.  I like the contrast and IR look.', '2008-10-18 13:17:55.000000', NULL, 1),
(5013504, 731105, 3087, '<td valign="top">This is great, it works really well. I''m mostly not really appreciating the entries where the image taken has simply been rotated by 180 degrees but in this case it works and creates a genuinely appealing abstract. I think what grounds it is the way that the door number still reads correctly even upside down. Great colours and textures in the brick.</td>', 'This is great, it works really well. I''m mostly not really appreciating the entries where the image taken has simply been rotated by 180 degrees but in this case it works and creates a genuinely appealing abstract. I think what grounds it is the way that the door number still reads correctly even upside down. Great colours and textures in the brick.', '2008-10-18 13:18:56.000000', NULL, 1),
(5013505, 730685, 86447, '<td valign="top">I still need the glass to be level... even though you might have meant it this way to emphasize the drinking part.  Nice reflection.  Good for the topic.  I wish the glass were sharper and less noise in the entire image.<br/> <br/>But, I wish I could get glass like IreneM... *sigh*  Easier said than done.  :)</td>', 'I still need the glass to be level... even though you might have meant it this way to emphasize the drinking part.  Nice reflection.  Good for the topic.  I wish the glass were sharper and less noise in the entire image. But, I wish I could get glass like IreneM... *sigh*  Easier said than done.  :)', '2008-10-18 13:19:07.000000', NULL, 1),
(5013506, 730890, 86447, '<td valign="top">Interesting... I like the sky... <br/> <br/>It seems a bit slanted toward the right (as is)... but that might be an illusion.</td>', 'Interesting... I like the sky...  It seems a bit slanted toward the right (as is)... but that might be an illusion.', '2008-10-18 13:19:46.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5013507, 730704, 3087, '<td valign="top">What I like about this is that you''ve achieved the challenge objective without simply taking an image and rotating it 180 degrees. You''ve looked for a situation where something, or in this case someone, has a genuine reason to be upside down. The quirky angles and the bright colours of her blue jeans, the yellow and red coats of the other kids and the muted green and gold of the ground all work well.</td>', 'What I like about this is that you''ve achieved the challenge objective without simply taking an image and rotating it 180 degrees. You''ve looked for a situation where something, or in this case someone, has a genuine reason to be upside down. The quirky angles and the bright colours of her blue jeans, the yellow and red coats of the other kids and the muted green and gold of the ground all work well.', '2008-10-18 13:20:06.000000', NULL, 1),
(5013508, 730396, 86447, '<td valign="top">Pretty image... I wish it were clearer and brighter or more contrast.  Also a tad bit sharper would have been beneficial, I think.</td>', 'Pretty image... I wish it were clearer and brighter or more contrast.  Also a tad bit sharper would have been beneficial, I think.', '2008-10-18 13:20:18.000000', NULL, 1),
(5013510, 730902, 86447, '<td valign="top">Great line of geese.   The blown part in ''real life'' is a bit distracting... but I realize to get the reflection so beautiful and the trees still good was difficult.</td>', 'Great line of geese.   The blown part in ''real life'' is a bit distracting... but I realize to get the reflection so beautiful and the trees still good was difficult.', '2008-10-18 13:21:25.000000', NULL, 1),
(5013512, 730201, 86447, '<td valign="top">This is a bit too dark and the shadow is distracting to me.   Maybe you could have moved it away from the wall a bit and used less DOF?</td>', 'This is a bit too dark and the shadow is distracting to me.   Maybe you could have moved it away from the wall a bit and used less DOF?', '2008-10-18 13:22:07.000000', NULL, 1),
(5013514, 731004, 86447, '<td valign="top">I wish there were more detail in the flower and petals.  Good idea for the challenge.</td>', 'I wish there were more detail in the flower and petals.  Good idea for the challenge.', '2008-10-18 13:22:29.000000', NULL, 1),
(5013515, 730822, 86447, '<td valign="top">I think the tilt of the clock away from the camera makes this not quite as good as it could have been.  Squaring up to the clock might have helped.</td>', 'I think the tilt of the clock away from the camera makes this not quite as good as it could have been.  Squaring up to the clock might have helped.', '2008-10-18 13:23:07.000000', NULL, 1),
(5013516, 731121, 86447, '<td valign="top">The flash shadow here is distracting.   I can''t imagine it was an easy shot to get, though.</td>', 'The flash shadow here is distracting.   I can''t imagine it was an easy shot to get, though.', '2008-10-18 13:23:34.000000', NULL, 1),
(5013518, 730071, 3087, '<td valign="top">The contrast between yellow and purple is very pretty.</td>', 'The contrast between yellow and purple is very pretty.', '2008-10-18 13:23:53.000000', NULL, 1),
(5013519, 731129, 86447, '<td valign="top">The houses need a bit of brightening, I fear.  As it is there doesn''t seem to be anything as the subject (in focus) other than where the water meets the water.  It leaves me wanting more.</td>', 'The houses need a bit of brightening, I fear.  As it is there doesn''t seem to be anything as the subject (in focus) other than where the water meets the water.  It leaves me wanting more.', '2008-10-18 13:24:59.000000', NULL, 1),
(5013520, 729637, 3087, '<td valign="top">I appreciate that you''ve looked for and found a sitation in which someone would naturally be upside down, rather than simply taken a picture and rotated it 180 degrees, as some entrants have!<br/>The sunlight through her hair is very pretty. I''d appreciate a shallowe DOF to blur the background out a touch more, but it works as is.</td>', 'I appreciate that you''ve looked for and found a sitation in which someone would naturally be upside down, rather than simply taken a picture and rotated it 180 degrees, as some entrants have!The sunlight through her hair is very pretty. I''d appreciate a shallowe DOF to blur the background out a touch more, but it works as is.', '2008-10-18 13:25:03.000000', NULL, 1),
(5013522, 731113, 86447, '<td valign="top">This is interesting... I wish that leaf (top, as shown) were not so out of focus.   Good color and contrast.</td>', 'This is interesting... I wish that leaf (top, as shown) were not so out of focus.   Good color and contrast.', '2008-10-18 13:25:35.000000', NULL, 1),
(5013523, 730470, 3087, '<td valign="top">I expected quite a few water reflections, rotated 180 degrees. This is my favourite, I think it works really well.</td>', 'I expected quite a few water reflections, rotated 180 degrees. This is my favourite, I think it works really well.', '2008-10-18 13:25:38.000000', NULL, 1),
(5013524, 729513, 3087, '<td valign="top">Yay, an effort to find something that is naturally upside down rather than just grab something and turn it over! Cute!</td>', 'Yay, an effort to find something that is naturally upside down rather than just grab something and turn it over! Cute!', '2008-10-18 13:26:09.000000', NULL, 1),
(5013525, 730397, 3087, '<td valign="top">Nice silhouette!</td>', 'Nice silhouette!', '2008-10-18 13:26:20.000000', NULL, 1),
(5013526, 730552, 86447, '<td valign="top">That dock is distracting to me.  I like the colors... but I think I would have cropped out the houses and the floating dock... or centered up the houses so there was something clearly as the subject.</td>', 'That dock is distracting to me.  I like the colors... but I think I would have cropped out the houses and the floating dock... or centered up the houses so there was something clearly as the subject.', '2008-10-18 13:26:27.000000', NULL, 1),
(5013527, 730877, 3087, '<td valign="top">Works well.</td>', 'Works well.', '2008-10-18 13:26:30.000000', NULL, 1),
(5013528, 730956, 3087, '<td valign="top">I like the way you''ve given most of the frame over to the reflection rather than the other way round. Works well.</td>', 'I like the way you''ve given most of the frame over to the reflection rather than the other way round. Works well.', '2008-10-18 13:27:07.000000', NULL, 1),
(5013529, 730728, 86447, '<td valign="top">Great idea for upside down!   I wish there were more detail in the ''real'' person... and the strong highlights on the top of the image (that the shadow is on) are a bit much... and then those hot spots where the top and bottom meet...  I gave this a 5.   It''s a tough shot to get.</td>', 'Great idea for upside down!   I wish there were more detail in the ''real'' person... and the strong highlights on the top of the image (that the shadow is on) are a bit much... and then those hot spots where the top and bottom meet...  I gave this a 5.   It''s a tough shot to get.', '2008-10-18 13:28:06.000000', NULL, 1),
(5013530, 729917, 3087, '<td valign="top">Aaaw, poor little critter! Cute image and I like your shallow DOF. Would be curious to see this one in colour too. Could do with more contrast in the black and white conversion I think or maybe it''s simply that there is too much mid-tone grey in the image and not much white and black?</td>', 'Aaaw, poor little critter! Cute image and I like your shallow DOF. Would be curious to see this one in colour too. Could do with more contrast in the black and white conversion I think or maybe it''s simply that there is too much mid-tone grey in the image and not much white and black?', '2008-10-18 13:28:11.000000', NULL, 1),
(5013532, 730356, 3087, '<td valign="top">I can''t imagine how you''ve achieved this! I''m ever so curious! :)</td>', 'I can''t imagine how you''ve achieved this! I''m ever so curious! :)', '2008-10-18 13:29:33.000000', NULL, 1),
(5013533, 731156, 86447, '<td valign="top">I think the shot has to stand on its own even outside the challenge to score highly.<br/> <br/>If I saw this not associated with the challenge, I would not like it.<br/> <br/>As it is, though, I like the colors but wish there were more detail in the fish''s body.</td>', 'I think the shot has to stand on its own even outside the challenge to score highly. If I saw this not associated with the challenge, I would not like it. As it is, though, I like the colors but wish there were more detail in the fish''s body.', '2008-10-18 13:29:34.000000', NULL, 1),
(5013534, 731157, 3087, '<td valign="top">Great abstract, really like it.</td>', 'Great abstract, really like it.', '2008-10-18 13:29:45.000000', NULL, 1),
(5013536, 730106, 3087, '<td valign="top">I like the idea.</td>', 'I like the idea.', '2008-10-18 13:30:12.000000', NULL, 1),
(5013537, 730922, 86447, '<td valign="top">I think the shot has to stand on its own even outside the challenge to score highly.  It''s a good idea... She doesn''t look strained enough to be realistically hanging from her feet.  <br/> <br/>I like how her hair almost looks like it''s hanging.  Maybe her jacket and pants bottoms could have been moved up to make them look like they were hanging, too?</td>', 'I think the shot has to stand on its own even outside the challenge to score highly.  It''s a good idea... She doesn''t look strained enough to be realistically hanging from her feet.   I like how her hair almost looks like it''s hanging.  Maybe her jacket and pants bottoms could have been moved up to make them look like they were hanging, too?', '2008-10-18 13:31:04.000000', NULL, 1),
(5013538, 730902, 3087, '<td valign="top">What an intriguing image. The 180 degree rotation does add something here, it makes me really peer at the image to work out what I''m seeing. The mist looks so strange upside down as does whatever is below the water surface in the foreground.</td>', 'What an intriguing image. The 180 degree rotation does add something here, it makes me really peer at the image to work out what I''m seeing. The mist looks so strange upside down as does whatever is below the water surface in the foreground.', '2008-10-18 13:31:33.000000', NULL, 1),
(5013539, 730982, 3087, '<td valign="top">So beautiful. I''m wondering whether it would have worked better as a portrait orientation image?</td>', 'So beautiful. I''m wondering whether it would have worked better as a portrait orientation image?', '2008-10-18 13:31:54.000000', NULL, 1),
(5013540, 730475, 86447, '<td valign="top">Nicely done... but not enough contrast for me... the background being yellow makes this seem like it has a yellow cast to it.  Some PP would have taken care of that, I think.   Nice job getting it all in focus.  Maybe a black border all around the image would have lessened the black line at the bottom.</td>', 'Nicely done... but not enough contrast for me... the background being yellow makes this seem like it has a yellow cast to it.  Some PP would have taken care of that, I think.   Nice job getting it all in focus.  Maybe a black border all around the image would have lessened the black line at the bottom.', '2008-10-18 13:32:30.000000', NULL, 1),
(5013541, 731035, 3087, '<td valign="top">Great image but I think it''s a LOT stronger without the 180 degree rotation.</td>', 'Great image but I think it''s a LOT stronger without the 180 degree rotation.', '2008-10-18 13:32:36.000000', NULL, 1),
(5013544, 730970, 86447, '<td valign="top">Nice and sharp on the butterfly eye.. .but the backlighting being so bright has a negative effect.  I wonder if you played with this in Photoshop or something a bit, it could have score more highly...</td>', 'Nice and sharp on the butterfly eye.. .but the backlighting being so bright has a negative effect.  I wonder if you played with this in Photoshop or something a bit, it could have score more highly...', '2008-10-18 13:33:34.000000', NULL, 1),
(5013545, 730819, 86447, '<td valign="top">I think this either needs more color or to be a true black and white image... as it is, it just seems muddy to me.  Needs more contrast, I think, to score more highly.  5</td>', 'I think this either needs more color or to be a true black and white image... as it is, it just seems muddy to me.  Needs more contrast, I think, to score more highly.  5', '2008-10-18 13:34:18.000000', NULL, 1),
(5013546, 731048, 86447, '<td valign="top">Great idea for the challenge topic.  I wish the face were more visible...</td>', 'Great idea for the challenge topic.  I wish the face were more visible...', '2008-10-18 13:35:02.000000', NULL, 1),
(5013547, 730896, 86447, '<td valign="top">I think the flame of the candle needs to be shown in the one on the left... to make the viewer realize that that''s what''s being reflected in the wine glass.   It took me a long bit of studying to figure it out.  <br/> <br/>Nice and sharp on the glass.</td>', 'I think the flame of the candle needs to be shown in the one on the left... to make the viewer realize that that''s what''s being reflected in the wine glass.   It took me a long bit of studying to figure it out.   Nice and sharp on the glass.', '2008-10-18 13:36:41.000000', NULL, 1),
(5013549, 730984, 86447, '<td valign="top">Great idea for the challenge.  I wish something were totally in focus, though...</td>', 'Great idea for the challenge.  I wish something were totally in focus, though...', '2008-10-18 13:37:15.000000', NULL, 1),
(5013551, 730339, 86447, '<td valign="top">The blown parts are making this score less than it would have with proper lighting, I fear.   Good idea for the challenge topic.  It''s a tough shot.</td>', 'The blown parts are making this score less than it would have with proper lighting, I fear.   Good idea for the challenge topic.  It''s a tough shot.', '2008-10-18 13:38:23.000000', NULL, 1),
(5013552, 729926, 86447, '<td valign="top">I think we need to see the entire cone... without that base chopped off.</td>', 'I think we need to see the entire cone... without that base chopped off.', '2008-10-18 13:39:00.000000', NULL, 1),
(5013553, 730925, 86447, '<td valign="top">Lovely colors... I wish the face/body were a bit more in focus.  Looks like it''s focused a bit back (on the rear leg).</td>', 'Lovely colors... I wish the face/body were a bit more in focus.  Looks like it''s focused a bit back (on the rear leg).', '2008-10-18 13:40:04.000000', NULL, 1),
(5013554, 731124, 86447, '<td valign="top">I think the shot has to stand on its own even outside the challenge to score highly.   So, if I were to see this outside the challenge, I would not think there was any purpose to turning it upside down.  Make sense?</td>', 'I think the shot has to stand on its own even outside the challenge to score highly.   So, if I were to see this outside the challenge, I would not think there was any purpose to turning it upside down.  Make sense?', '2008-10-18 13:40:58.000000', NULL, 1),
(5013582, 730538, 86447, '<td valign="top">Lovely reflection... I think I need a bit of ''real'' life to give perspective.</td>', 'Lovely reflection... I think I need a bit of ''real'' life to give perspective.', '2008-10-18 14:39:15.000000', NULL, 1),
(5013584, 730977, 86447, '<td valign="top">The ''real'' part has some blown trees that are most likely affecting your score.   Nice reflection.</td>', 'The ''real'' part has some blown trees that are most likely affecting your score.   Nice reflection.', '2008-10-18 14:39:49.000000', NULL, 1),
(5013585, 730989, 86447, '<td valign="top">Pretty... I might have cropped it differently to allow the image to be larger and still stay under the 150K.   Smaller images just don''t seem to score well here on DPC.  <br/> <br/>Lovely colors... and the dark of the trunks works well for contrast.</td>', 'Pretty... I might have cropped it differently to allow the image to be larger and still stay under the 150K.   Smaller images just don''t seem to score well here on DPC.   Lovely colors... and the dark of the trunks works well for contrast.', '2008-10-18 14:40:49.000000', NULL, 1),
(5013586, 729899, 86447, '<td valign="top">While this fits the challenge topic very well... it''s just not an exciting subject for a photograph, I fear.</td>', 'While this fits the challenge topic very well... it''s just not an exciting subject for a photograph, I fear.', '2008-10-18 14:41:17.000000', NULL, 1),
(5013587, 730815, 86447, '<td valign="top">It seems a bit crowded... more space on the sides and top would have appealed to me more.  5</td>', 'It seems a bit crowded... more space on the sides and top would have appealed to me more.  5', '2008-10-18 14:41:43.000000', NULL, 1),
(5013590, 730680, 86447, '<td valign="top">Cute mantis.  I don''t get the ''upside down'' part, though.  I think the exposure could have been adjusted here to really make this image ''pop''.</td>', 'Cute mantis.  I don''t get the ''upside down'' part, though.  I think the exposure could have been adjusted here to really make this image ''pop''.', '2008-10-18 14:42:29.000000', NULL, 1),
(5013593, 730894, 86447, '<td valign="top">It seems that his ... umm.... his bottom is more sharply focused than his face.  I''m sure this is affecting the score.   He''s cute, though.  :)</td>', 'It seems that his ... umm.... his bottom is more sharply focused than his face.  I''m sure this is affecting the score.   He''s cute, though.  :)', '2008-10-18 14:43:32.000000', NULL, 1),
(5013597, 729925, 86447, '<td valign="top">There''s nothing here to hold my interest, I fear.   It''s a good photo of a wall, but why?</td>', 'There''s nothing here to hold my interest, I fear.   It''s a good photo of a wall, but why?', '2008-10-18 14:44:18.000000', NULL, 1),
(5013598, 729625, 86447, '<td valign="top">This could use some extra PP to make it really exciting.   It seems a bit flat to me.</td>', 'This could use some extra PP to make it really exciting.   It seems a bit flat to me.', '2008-10-18 14:44:42.000000', NULL, 1),
(5013600, 730357, 86447, '<td valign="top">The lighting could be better here, I think.  The lower right light is blown and affects the arm and face.   Good idea for the challenge topic.</td>', 'The lighting could be better here, I think.  The lower right light is blown and affects the arm and face.   Good idea for the challenge topic.', '2008-10-18 14:45:27.000000', NULL, 1),
(5013603, 730488, 86447, '<td valign="top">This might be better without hte bushes.. .more of an abstract then, I think.<br/> <br/>As it is, the bushes seem like the subject and they''re not interesting enough to hold my attention.  But, I''m just one of many.  Everybody else might love it.  :)</td>', 'This might be better without hte bushes.. .more of an abstract then, I think. As it is, the bushes seem like the subject and they''re not interesting enough to hold my attention.  But, I''m just one of many.  Everybody else might love it.  :)', '2008-10-18 14:46:25.000000', NULL, 1),
(5013605, 731120, 86447, '<td valign="top">this seems too dark to me to be really interesting.  I need to see the line where the water meets the real life, I think.</td>', 'this seems too dark to me to be really interesting.  I need to see the line where the water meets the real life, I think.', '2008-10-18 14:47:08.000000', NULL, 1),
(5013610, 731110, 86447, '<td valign="top">On my monitor, this adorable dog''s ears have merged into the blackness behind and he looks like he lost half of his head.   I like the sharpness on the eyes and the catchlights in them.   Good idea for the challenge topic.</td>', 'On my monitor, this adorable dog''s ears have merged into the blackness behind and he looks like he lost half of his head.   I like the sharpness on the eyes and the catchlights in them.   Good idea for the challenge topic.', '2008-10-18 14:48:18.000000', NULL, 1),
(5013612, 730978, 86447, '<td valign="top">Pretty colors... but that lower left part keeps grabbing my attention and it looks blown.  I also think I need to see the line where the reflection meets ''real life''.</td>', 'Pretty colors... but that lower left part keeps grabbing my attention and it looks blown.  I also think I need to see the line where the reflection meets ''real life''.', '2008-10-18 14:49:06.000000', NULL, 1),
(5013616, 731069, 86447, '<td valign="top">Beautiful!   One of my top picks.  The colors and the smoothness are wonderful.  I predict a ribbon for you.  :)</td>', 'Beautiful!   One of my top picks.  The colors and the smoothness are wonderful.  I predict a ribbon for you.  :)', '2008-10-18 14:52:06.000000', NULL, 1),
