INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5020113, 730966, 40386, '<td valign="top">Greak finish Barry, three guys in the top 30, go Team UK!!<br/></td>', 'Greak finish Barry, three guys in the top 30, go Team UK!!', '2008-10-22 09:36:00.000000', NULL, 0),
(5020128, 730356, 87808, '<td valign="top">Great shot H, I don''t understand all those 1,2,3,4 votes.  You should have this as a print.</td>', 'Great shot H, I don''t understand all those 1,2,3,4 votes.  You should have this as a print.', '2008-10-22 09:48:07.000000', NULL, 0),
(5020145, 731116, 55005, '<td valign="top">Congrats, Damian!</td>', 'Congrats, Damian!', '2008-10-22 09:55:02.000000', NULL, 0),
(5020147, 730690, 55005, '<td valign="top">Congrats, Adam!  :)</td>', 'Congrats, Adam!  :)', '2008-10-22 09:57:22.000000', NULL, 0),
(5020150, 730788, 55005, '<td valign="top">Excellent image, Erik!  Those clouds really made this shot.  Congrats on the 5th!</td>', 'Excellent image, Erik!  Those clouds really made this shot.  Congrats on the 5th!', '2008-10-22 09:58:18.000000', NULL, 0),
(5020152, 731058, 65234, '<td valign="top">Much too clear a reflection.  You clearly confused everyone by shooting a reflection which was upside down but when viewed upside down made the building look right side up.  People don''t like to have to analyze images, it makes their brains hurt.  What were you thinking??  Next time drop a pebble in the water (automatic bonus for showing water, too).</td>', 'Much too clear a reflection.  You clearly confused everyone by shooting a reflection which was upside down but when viewed upside down made the building look right side up.  People don''t like to have to analyze images, it makes their brains hurt.  What were you thinking??  Next time drop a pebble in the water (automatic bonus for showing water, too).', '2008-10-22 09:59:50.000000', NULL, 0),
(5020154, 729917, 88204, '<td valign="top">I love this shot! Very whimsical and fun. The spread legs really make it. The composition, DoF and B&amp;W really help to get that feel across. Excellent!</td>', 'I love this shot! Very whimsical and fun. The spread legs really make it. The composition, DoF and B&W really help to get that feel across. Excellent!', '2008-10-22 10:00:19.000000', NULL, 0),
(5020159, 731058, 89341, '<td valign="top">Pretty much nothing to add to what the others said, it''s a great image but I suspect you were a victim of not forcing the image into peoples faces :)</td>', 'Pretty much nothing to add to what the others said, it''s a great image but I suspect you were a victim of not forcing the image into peoples faces :)', '2008-10-22 10:05:53.000000', NULL, 0),
(5020164, 730293, 65234, '<td valign="top">Ew; it''s hairy and everything!  I can practically see blood dripping off of it''s fangs!!<br/> <br/>It''s positioned appropriately for the challenge and I like the DOF and detail (ignoring the fact that it''s a SPIDER).  I didn''t vote in this one, but this looks like a 6 to me.  Maybe tilt it a little more to the left and it would make more people think of it as upside down.</td>', 'Ew; it''s hairy and everything!  I can practically see blood dripping off of it''s fangs!! It''s positioned appropriately for the challenge and I like the DOF and detail (ignoring the fact that it''s a SPIDER).  I didn''t vote in this one, but this looks like a 6 to me.  Maybe tilt it a little more to the left and it would make more people think of it as upside down.', '2008-10-22 10:08:33.000000', NULL, 0),
(5020169, 729691, 89341, '<td valign="top">The colours are awesome, nice and vibrant, fits challenge well IMHO.<br/> <br/>I personally would have preferred a larger dof on the wings I think, maybe thats what hurt you a bit but as fir all the 1-3''s????? I didn''t vote but would have given this a 6 or 7</td>', 'The colours are awesome, nice and vibrant, fits challenge well IMHO. I personally would have preferred a larger dof on the wings I think, maybe thats what hurt you a bit but as fir all the 1-3''s????? I didn''t vote but would have given this a 6 or 7', '2008-10-22 10:13:17.000000', NULL, 0),
(5020174, 730970, 83313, '<td valign="top">This didn''t come up for me in voting. I like it. Good use of DOF (which is harder to achieve  on a small sensor camera), good color and detail, and a very good twist on a common subject. Love the title, btw. My nitpick on this one is that I may have not cropped it so centered. I''m surprised at the low 5 it averaged, but this was a low averaging challenge for some reason. If it had come up in voting, I think I would have given it a 6. If you''d cropped it differently and maybe been able to coax more detail out of the wings, I might call it a 7.</td>', 'This didn''t come up for me in voting. I like it. Good use of DOF (which is harder to achieve  on a small sensor camera), good color and detail, and a very good twist on a common subject. Love the title, btw. My nitpick on this one is that I may have not cropped it so centered. I''m surprised at the low 5 it averaged, but this was a low averaging challenge for some reason. If it had come up in voting, I think I would have given it a 6. If you''d cropped it differently and maybe been able to coax more detail out of the wings, I might call it a 7.', '2008-10-22 10:15:56.000000', NULL, 0),
(5020176, 729899, 89341, '<td valign="top">Nice colours but I tend to agree with what others have said, not quite exciting enough ... maybe removing the top level of items and adding more cups to form a pattern (with a different cup in there somewhere to add some interest)</td>', 'Nice colours but I tend to agree with what others have said, not quite exciting enough ... maybe removing the top level of items and adding more cups to form a pattern (with a different cup in there somewhere to add some interest)', '2008-10-22 10:16:26.000000', NULL, 0),
